import React, { useEffect, useState } from 'react';
import { Box, Typography, Drawer, List, ListItem, ListItemIcon, ListItemText, AppBar, Toolbar, IconButton, Button, Avatar, useMediaQuery, Divider, Paper, Grid, TextField, InputAdornment, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Snackbar, Alert } from '@mui/material';
import MenuIcon from '@mui/icons-material/Menu';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import LinkIcon from '@mui/icons-material/Link';
import FolderIcon from '@mui/icons-material/Folder';
import AccountBalanceWalletIcon from '@mui/icons-material/AccountBalanceWallet';
import ShareIcon from '@mui/icons-material/Share';

const drawerWidth = 240;

const user = { name: 'ak editz', email: 'ak7477586@gmail.com' };

const menuItems = [
  { text: 'Revenue Data', icon: <AttachMoneyIcon sx={{ color: '#00b050' }} /> },
  { text: 'Link Data', icon: <LinkIcon sx={{ color: '#00b050' }} /> },
  { text: 'My file', icon: <FolderIcon sx={{ color: '#00b050' }} /> },
  { text: 'Withdraw', icon: <AccountBalanceWalletIcon sx={{ color: '#00b050' }} /> },
];

// Dummy data for earnings table
const earningsData = [
  // Uncomment below to test with data
  // { date: '2024-05-20', total: 2.50, views: 1250, earning: 2.50 },
  // { date: '2024-05-19', total: 1.00, views: 500, earning: 1.00 },
];

function RevenueDataSection() {
  const isMobile = useMediaQuery('(max-width:600px)');
  const [stats, setStats] = useState({ views: 0, earning: 0 });

  useEffect(() => {
    // Get user email from JWT token in localStorage
    const token = localStorage.getItem('token');
    if (!token) return;
    // Decode JWT to get email (simple base64 decode, not secure for prod)
    try {
      const payload = JSON.parse(atob(token.split('.')[1]));
      const email = payload.email;
      fetch('/api/analytics/all-users')
        .then(res => res.json())
        .then(users => {
          if (Array.isArray(users)) {
            const user = users.find(u => u.email === email);
            if (user) setStats({ views: user.views || 0, earning: user.earning || 0 });
          }
        });
    } catch (e) {}
  }, []);

  return (
    <Box>
      {/* Earnings summary cards */}
      <Grid container spacing={2} mb={2}>
        <Grid item xs={12} sm={4}>
          <Paper elevation={2} sx={{ p: 2, borderRadius: 3, textAlign: 'center' }}>
            <Typography variant="h6" fontWeight={700}>Total Earnings</Typography>
            <Typography variant="h4" fontWeight={900} color="#00b050">${stats.earning.toFixed(2)}</Typography>
            <Typography variant="caption" color="text.secondary">All time</Typography>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Paper elevation={2} sx={{ p: 2, borderRadius: 3, textAlign: 'center' }}>
            <Typography variant="h6" fontWeight={700}>Total Views</Typography>
            <Typography variant="h4" fontWeight={900} color="#7c3aed">{stats.views}</Typography>
            <Typography variant="caption" color="text.secondary">All time</Typography>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Paper elevation={2} sx={{ p: 2, borderRadius: 3, textAlign: 'center' }}>
            <Typography variant="h6" fontWeight={700}>Withdrawn</Typography>
            <Typography variant="h4" fontWeight={900} color="#00b050">$0.00</Typography>
            <Typography variant="caption" color="text.secondary">Total withdrawn</Typography>
          </Paper>
        </Grid>
      </Grid>
      {/* Revenue Table or No Data State */}
      <Paper elevation={2} sx={{ p: isMobile ? 1 : 3, borderRadius: 3, mb: 2 }}>
        <Typography variant="h6" fontWeight={700} mb={2}>Revenue</Typography>
        {stats.views === 0 ? (
          <Box sx={{ textAlign: 'center', py: 4 }}>
            <Typography color="text.secondary" mb={2}>No data, make money by sharing videos</Typography>
            <Button variant="contained" startIcon={<ShareIcon />} sx={{ bgcolor: '#00b050', borderRadius: 8, fontWeight: 700, px: 4, py: 1.2, fontSize: 18, boxShadow: '0 2px 12px #00b05044', '&:hover': { bgcolor: '#00913a' } }}>
              To share
            </Button>
          </Box>
        ) : (
          <Typography color="text.secondary" mb={2}>You have {stats.views} views. Your earning: ${stats.earning.toFixed(2)}</Typography>
        )}
      </Paper>
    </Box>
  );
}

function LinkDataSection() {
  return (
    <Paper elevation={2} sx={{ p: 3, borderRadius: 3, mb: 2 }}>
      <Typography variant="h6" fontWeight={700} mb={1}>Shared link</Typography>
      <Typography variant="body2" color="text.secondary" mb={2}>
        Only display the top 10 items with the highest number of views. Shared links start counting from May 13, 2024
      </Typography>
      <Paper elevation={0} sx={{ p: 4, textAlign: 'center', bgcolor: '#fafbfc' }}>
        <Typography color="text.secondary">No Data</Typography>
      </Paper>
    </Paper>
  );
}

function MyFileSection() {
  const [videos, setVideos] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [link, setLink] = useState('');
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

  // Get userId from JWT
  function getUserId() {
    const token = localStorage.getItem('token');
    if (!token) return null;
    try {
      const payload = JSON.parse(atob(token.split('.')[1]));
      return payload.id;
    } catch (e) { return null; }
  }

  // Fetch user's videos
  useEffect(() => {
    const userId = getUserId();
    if (!userId) return;
    fetch(`/api/video?userId=${userId}`)
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) setVideos(data.reverse());
        else setVideos([]);
      });
  }, [uploading]);

  // Handle video upload
  const handleUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true);
    setLink('');
    const userId = getUserId();
    const formData = new FormData();
    formData.append('video', file);
    formData.append('userId', userId);
    try {
      const res = await fetch('/api/video/upload', { method: 'POST', body: formData });
      const data = await res.json();
      if (res.ok && data.link) {
        setLink(data.link);
        setSnackbar({ open: true, message: 'Video uploaded! Link copied.', severity: 'success' });
        navigator.clipboard.writeText(data.link);
      } else {
        setSnackbar({ open: true, message: data.message || 'Upload failed', severity: 'error' });
      }
    } catch (err) {
      setSnackbar({ open: true, message: 'Upload failed', severity: 'error' });
    }
    setUploading(false);
  };

  return (
    <Paper elevation={2} sx={{ p: 3, borderRadius: 3, mb: 2 }}>
      <Box sx={{ display: 'flex', gap: 2, mb: 2, flexWrap: 'wrap' }}>
        <Button
          variant="contained"
          component="label"
          sx={{ bgcolor: '#00b050', borderRadius: 2, fontWeight: 700 }}
          disabled={uploading}
        >
          {uploading ? 'Uploading...' : 'Upload Video'}
          <input type="file" accept="video/*" hidden onChange={handleUpload} />
        </Button>
        <Button variant="outlined" sx={{ borderColor: '#00b050', color: '#00b050', borderRadius: 2, fontWeight: 700 }}>New Folder</Button>
        <TextField placeholder="Search Files" size="small" sx={{ ml: 'auto', width: 200 }} InputProps={{ endAdornment: <Button sx={{ color: '#00b050', fontWeight: 700 }}>Search</Button> }} />
      </Box>
      {link && (
        <Alert severity="success" sx={{ mb: 2 }}>
          Video link: <a href={link} target="_blank" rel="noopener noreferrer">{link}</a> (copied!)
        </Alert>
      )}
      <TableContainer component={Paper} sx={{ mt: 2 }}>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Video</TableCell>
              <TableCell>Link</TableCell>
              <TableCell>Views</TableCell>
              <TableCell>Earning ($)</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {videos.length === 0 ? (
              <TableRow><TableCell colSpan={4} align="center">No videos uploaded yet.</TableCell></TableRow>
            ) : (
              videos.map((video, idx) => (
                <TableRow key={idx}>
                  <TableCell>
                    <video src={video.url} width={80} controls style={{ maxHeight: 60 }} />
                  </TableCell>
                  <TableCell>
                    <a href={`${window.location.origin}/v/${video.videoId}`} target="_blank" rel="noopener noreferrer">
                      {window.location.origin}/v/{video.videoId}
                    </a>
                  </TableCell>
                  <TableCell>{video.views || 0}</TableCell>
                  <TableCell>{video.earning ? video.earning.toFixed(2) : '0.00'}</TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>
      <Snackbar open={snackbar.open} autoHideDuration={4000} onClose={() => setSnackbar({ ...snackbar, open: false })}>
        <Alert onClose={() => setSnackbar({ ...snackbar, open: false })} severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Paper>
  );
}

